svg.script:
(function () {
  "use strict";

  var BASE = "https://cdn.jsdelivr.net/gh/fusion-webv3/fusion-game@main/fusion_v";
  var EXT = ".svg";
  var MAX_VERSION = 500;                       // safety cap for the probing loop
  var XHTML = "http://www.w3.org/1999/xhtml";
  var ALLOW = "fullscreen; autoplay; clipboard-write; gamepad";
  var STORE_KEY = "fusion_loader_last_version";
  var BG = "#0b0b10";

  var host = document.getElementById("host");
  var stage = document.getElementById("stage");
  var status = document.getElementById("status");

  // Keep the foreignObject and stage exactly the size of the window, in real pixels, no scaling.
  // The browser already reports a new window size when the page is zoomed in or out (the CSS-pixel
  // viewport shrinks or grows), so re-reading it here keeps the frame edge to edge at any zoom level.
  function fit() {
    var w = window.innerWidth || document.documentElement.clientWidth;
    var h = window.innerHeight || document.documentElement.clientHeight;
    host.setAttribute("width", w);
    host.setAttribute("height", h);
    stage.style.width = w + "px";
    stage.style.height = h + "px";
  }
  fit();
  window.addEventListener("resize", fit);
  window.addEventListener("orientationchange", fit);
  window.addEventListener("pageshow", fit);

  function versionUrl(n) { return BASE + n + EXT; }
  function setStatus(msg) { status.textContent = msg; }

  /* ---- remembering the newest version ---- */
  function readSaved() {
    try {
      var n = parseInt(localStorage.getItem(STORE_KEY), 10);
      return n >= 1 && n <= MAX_VERSION ? n : 0;
    } catch (err) { return 0; }
  }
  function writeSaved(n) {
    try { localStorage.setItem(STORE_KEY, String(n)); } catch (err) {}
  }

  /* ---- finding the newest version ---- */
  // true = exists, false = missing (404 etc.), null = network error
  async function exists(n) {
    try {
      var res = await fetch(versionUrl(n), { method: "HEAD", cache: "no-store" });
      return res.ok;
    } catch (err) { return null; }
  }

  // Start at the saved version (if it's still there) and probe upward until one is missing.
  // Falls back to scanning from v1 if the saved version is gone. Returns the highest version found (0 = none).
  async function findLatestVersion() {
    var best = 0;
    var saved = readSaved();
    if (saved) {
      var ok = await exists(saved);
      if (ok) best = saved;
      else if (ok === null) return saved;       // offline: just try the saved one
    }
    for (var n = best + 1; n <= MAX_VERSION; n++) {
      var found = await exists(n);
      if (!found) break;                        // 404 -> n-1 was the newest (or network dropped)
      best = n;
      setStatus("Found version " + n + "…");
    }
    return best;
  }

  /* ---- showing the loaded site ---- */
  // The frame always covers the whole page. It stays invisible (opacity 0) until it has loaded, and its own
  // background is dark, so a white page is never visible, not while loading and not on resize.
  function makeFrame(title) {
    var f = document.createElementNS(XHTML, "iframe");
    f.setAttribute("title", title || "FUSION");
    f.setAttribute("style",
      "position:absolute;top:0;left:0;width:100%;height:100%;min-width:100%;min-height:100%;" +
      "margin:0;padding:0;border:0;display:block;background:" + BG + ";color-scheme:dark;" +
      "opacity:0;transition:opacity .25s ease");
    f.setAttribute("allow", ALLOW);
    return f;
  }

  // Pull the code out of the fetched SVG and run it inside this one.
  function mount(svgText) {
    var frame = null;

    // 1) Same format the bundler writes: <foreignObject><iframe srcdoc="…">. Reuse its srcdoc directly.
    try {
      var doc = new DOMParser().parseFromString(svgText, "image/svg+xml");
      if (!doc.getElementsByTagName("parsererror").length) {
        var iframes = doc.getElementsByTagNameNS(XHTML, "iframe");
        var src = iframes.length ? iframes[0] : null;
        if (src && src.hasAttribute("srcdoc")) {
          frame = makeFrame(src.getAttribute("title"));
          if (src.hasAttribute("allow")) frame.setAttribute("allow", src.getAttribute("allow"));
          frame.setAttribute("srcdoc", src.getAttribute("srcdoc"));
        }
      }
    } catch (err) { /* fall through to the generic path */ }

    // 2) Any other SVG: run it as its own document in a blob iframe so its scripts and styles still work.
    if (!frame) {
      frame = makeFrame("FUSION");
      frame.setAttribute("src", URL.createObjectURL(new Blob([svgText], { type: "image/svg+xml" })));
    }

    // Show the frame, then remove the status text, only once the site has loaded.
    var revealed = false;
    function reveal() {
      if (revealed) return;
      revealed = true;
      frame.style.opacity = "1";
      setTimeout(function () { if (status.parentNode) status.parentNode.removeChild(status); }, 300);
    }
    frame.addEventListener("load", reveal);
    setTimeout(reveal, 10000);                  // never leave the status text up forever
    stage.insertBefore(frame, status);
  }

  async function boot() {
    try {
      var v = await findLatestVersion();
      if (!v) throw new Error("fusion_v1" + EXT + " could not be reached");
      setStatus("Loading version " + v + "…");
      var res = await fetch(versionUrl(v), { cache: "no-store" });
      if (!res.ok) throw new Error("HTTP " + res.status + " for version " + v);
      mount(await res.text());
      writeSaved(v);
    } catch (err) {
      setStatus("Couldn't load FUSION: " + err.message);
    }
  }

  boot();
})();
